public static String hadoopFsFilename(String fname, Configuration conf, String user)
        throws URISyntaxException, FileNotFoundException, IOException,
        InterruptedException {
        Path p = hadoopFsPath(fname, conf, user);
        if (p == null)
            return null;
        else
            return p.toString();
    }
